// Directory Accounts for Universal Smart Search & Verification (auto-suggest & auto-fill)
export const BULK_DIRECTORY_ACCOUNTS: RegisteredAccountInfo[] = BULK_REGISTERED_ACCOUNTS.map(e => ({
  accountNumber: e.accountNumber,
  accountName: e.name,
  bankName: e.bankName,
  userId: e.id,
  phone: e.phone,
  isVerified: true,
  accountType: 'Savings Account',
  balance: e.balance
}));

// UserProfiles for LocalDb user directory
export const BULK_USERS_SEED: UserProfile[] = BULK_REGISTERED_ACCOUNTS.map(e => ({
  id: e.id,
  name: e.name,
  phone: e.phone,
  email: e.email,
  role: 'user',
  status: 'active',
  createdAt: '2026-03-01T10:00:00Z',
  accountNumber: e.accountNumber,
  balance: e.balance,
  availableBalance: e.availableBalance,
  biometricEnabled: true
}));

// BankAccounts (one per unique account number with registered user as owner)
export const BULK_BANK_ACCOUNTS: BankAccount[] = BULK_REGISTERED_ACCOUNTS.map(e => ({
  id: 'acc_' + e.id,
  userId: e.id,
  accountName: e.name + ' Savings Account',
  accountNumber: e.accountNumber,
  accountType: 'savings',
  balance: e.balance,
  availableBalance: e.availableBalance,
  status: 'active',
  currency: 'ETB',
  isPrimary: true,
  createdAt: '2026-03-01T10:00:00Z'
}));
